<script setup lang="ts">import { computed } from 'vue'; import { useUiKit } from '../../platform/uiKit'; const props = defineProps<{ title?: string; description?: string; retryLabel?: string }>(); const emit = defineEmits<{ retry: [] }>(); const ui = useUiKit(); const title = computed(() => props.title ?? ui.t('errorTitle')); const description = computed(() => props.description ?? ui.t('errorDescription'));</script>
<template><section class="ui-state" :dir="ui.direction.value" role="alert"><slot name="icon"><component :is="ui.icon('error')" class="ui-state__icon" aria-hidden="true" /></slot><div><slot><strong>{{ title }}</strong><p>{{ description }}</p></slot><div class="ui-state__actions"><slot name="actions"><button type="button" class="ui-state__button" @click="emit('retry')"><component :is="ui.icon('retry')" aria-hidden="true" />{{ retryLabel ?? ui.t('retry') }}</button></slot></div></div></section></template>
